308		// 不再产生第二条交接（同岗位校验只对首次交接保留）。
309		if _, err := f.svc.CreateHandover(a.ID, other.ID); !errors.Is(err, ErrHandoverTarget) {
310			t.Fatalf("已有交接时改指其他岗位应按改换对象拒绝，got %v", err)
311		}
312		// 接班班次必须尚未结束：用一个没有接班交接的班次 d，先结束再作为接班对象。
313		d := mustShift(t, f, "调度", "钱七", tsDay(3, 8, 0), tsDay(3, 16, 0), "")
314		if _, err := f.svc.CloseShift(d.ID); err != nil {
315			t.Fatalf("close d: %v", err)
316		}
317		if _, err := f.svc.CreateHandover(c.ID, d.ID); !errors.Is(err, ErrShiftClosed) {
318			t.Fatalf("已结束的接班班次应报错，got %v", err)
319		}
320		// 交班班次未结束不能发起。
