1508			t.Fatalf("继续跟踪后事项应进入接班班次并更新后续负责人：%+v", it)
1509		}
1510		// 已接收项不能再退回，也不能重新提交。
1511		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "再退", "", ""); !errors.Is(err, ErrHandoverState) {
1512			t.Fatalf("已接收项不能退回，got %v", err)
1513		}
1514		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "不应写入"); !errors.Is(err, ErrHandoverState) {
1515			t.Fatalf("继续跟踪项不能重新提交，got %v", err)
1516		}
1517	}
1518	
1519	// TestResubmitStateAndInputRules：只有退回项可重新提交；待处理、已确认、
1520	// 继续跟踪都报状态错误且不写入补充；操作人必填、纯空格补充视为空。
1521	func TestResubmitStateAndInputRules(t *testing.T) {
1522		f := newFixture(t)
1523		a, b, items := prepareHandover(t, f)
1524		h, _ := f.svc.CreateHandover(a.ID, b.ID)
1525		idA, idB := items[0].ID, items[1].ID
1526	
1527		// 待处理项重新提交：状态错误，不写入。
1528		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "补充内容"); !errors.Is(err, ErrHandoverState) {
1529			t.Fatalf("待处理项重新提交应报 ErrHandoverState，got %v", err)
1530		}
1531		got, _ := f.svc.GetHandover(h.ID)
1532		ea := findEntryOf(t, got, idA)
1533		if len(ea.Rounds) != 0 || ea.Status != EntryPending {
1534			t.Fatalf("状态错误时不应写入补充或退回记录：%+v", ea)
1535		}
1536	
1537		// 已确认项重新提交：状态错误。
1538		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
1539			t.Fatalf("confirm: %v", err)
1540		}
1541		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "补充内容"); !errors.Is(err, ErrHandoverState) {
1542			t.Fatalf("已确认项重新提交应报错，got %v", err)
1543		}
1544	
1545		// 继续跟踪项重新提交：状态错误。
1546		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionTrack, "李四", "", "盯住", "王五"); err != nil {
1547			t.Fatalf("track: %v", err)
1548		}
1549		if _, err := f.svc.ResubmitReturned(h.ID, idB, "张三", "补充内容"); !errors.Is(err, ErrHandoverState) {
1550			t.Fatalf("继续跟踪项重新提交应报错，got %v", err)
1551		}
1552	
1553		// 退回后：操作人缺失、纯空格补充均为输入错误，且不写入。idA/idB 都已接收，
1554		// 另起一套数据制造退回项。
1555		f2 := newFixture(t)
1556		a2, b2, items2 := prepareHandover(t, f2)
1557		h3, _ := f2.svc.CreateHandover(a2.ID, b2.ID)
1558		id := items2[0].ID
1559		if _, err := f2.svc.ProcessEntry(h3.ID, id, ActionReturn, "李四", "需补充", "", ""); err != nil {
1560			t.Fatalf("return: %v", err)
1561		}
1562		if _, err := f2.svc.ResubmitReturned(h3.ID, id, "   ", "补充"); !errors.Is(err, ErrInvalidInput) {
1563			t.Fatalf("操作人必填，got %v", err)
1564		}
1565		if _, err := f2.svc.ResubmitReturned(h3.ID, id, "张三", "   "); !errors.Is(err, ErrInvalidInput) {
1566			t.Fatalf("纯空格补充说明应视为空，got %v", err)
1567		}
1568		g, _ := f2.svc.GetHandover(h3.ID)
1569		e := findEntryOf(t, g, id)
1570		if e.Status != EntryReturned || len(e.Rounds) != 1 || e.Rounds[0].Supplement != "" ||
1571			e.Rounds[0].ResubmittedAt != nil || e.Operator != "李四" {
1572			t.Fatalf("输入校验失败不得写入任何内容：%+v", e)
1573		}
1574		if _, err := f2.svc.ResubmitReturned(h3.ID, "I999", "张三", "补充"); !errors.Is(err, ErrNotFound) {
1575			t.Fatalf("清单外事项应 ErrNotFound，got %v", err)
1576		}
1577		if _, err := f2.svc.ResubmitReturned("H999", id, "张三", "补充"); !errors.Is(err, ErrNotFound) {
1578			t.Fatalf("不存在交接应 ErrNotFound，got %v", err)
1579		}
1580	
1581		// 重复重新提交已恢复待处理的事项也要报状态错误（不能二次写入同一轮）。
1582		if _, err := f2.svc.ResubmitReturned(h3.ID, id, "张三", "第一次补充"); err != nil {
1583			t.Fatalf("first resubmit: %v", err)
1584		}
1585		if _, err := f2.svc.ResubmitReturned(h3.ID, id, "张三", "再次补充"); !errors.Is(err, ErrHandoverState) {
1586			t.Fatalf("已重新提交、等待处理的事项不能再次补充提交，got %v", err)
1587		}
1588		g, _ = f2.svc.GetHandover(h3.ID)
1589		e = findEntryOf(t, g, id)
1590		if e.Rounds[0].Supplement != "第一次补充" {
1591			t.Fatalf("重复重新提交失败不得覆盖原补充：%+v", e.Rounds[0])
1592		}
1593	}
