1595	// TestReturnedQueriesShowPendingAsUnprocessed：交接查询与按班次查询一致展示
1596	// 当前结果与逐轮退回、补充记录；重新提交后接班处理人和处理时间显示尚未处理。
1597	func TestReturnedQueriesShowPendingAsUnprocessed(t *testing.T) {
