1611		if !strings.Contains(htext, "尚未处理") {
1612			t.Fatalf("交接查询应把恢复待处理项显示为尚未处理：\n%s", htext)
1613		}
1614		if !strings.Contains(htext, "第1次退回") || !strings.Contains(htext, "需补充图纸") ||
1615			!strings.Contains(htext, "图纸在B层") || !strings.Contains(htext, "已重新提交") {
1616			t.Fatalf("交接查询应逐轮展示退回原因、补充与重新提交：\n%s", htext)
1617		}
1618	
1619		rep, err := f.svc.ShiftReport(b.ID)
1620		if err != nil {
1621			t.Fatalf("report: %v", err)
1622		}
1623		rtext := FormatReport(rep)
1624		if !strings.Contains(rtext, "处理人=尚未处理") || !strings.Contains(rtext, "处理时间=尚未处理") {
1625			t.Fatalf("按班次查询当前结果应显示尚未处理：\n%s", rtext)
1626		}
1627		if !strings.Contains(rtext, "第1次退回") || !strings.Contains(rtext, "图纸在B层") ||
1628			!strings.Contains(rtext, "已重新提交") {
1629			t.Fatalf("按班次查询应逐轮展示退回与补充、重新提交记录：\n%s", rtext)
1630		}
1631	}
1632	
1633	func mustGetHandover(t *testing.T, f *fixture, id string) Handover {
1634		t.Helper()
1635		h, err := f.svc.GetHandover(id)
1636		if err != nil {
1637			t.Fatalf("get handover: %v", err)
1638		}
1639		return h
