1642	// TestReturnedStatePersistsAcrossReopen：退回后退出重开，未重新提交仍不能处理；
1643	// 重新提交与后续处理、完成状态在重开后均保留。
1644	func TestReturnedStatePersistsAcrossReopen(t *testing.T) {
1645		f := newFixture(t)
1646		a, b, items := prepareHandover(t, f)
1647		h, _ := f.svc.CreateHandover(a.ID, b.ID)
1648		idA, idB := items[0].ID, items[1].ID
1649		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "需补充", "", ""); err != nil {
1650			t.Fatalf("return: %v", err)
1651		}
1652		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
1653			t.Fatalf("confirm: %v", err)
