25	}
26	
27	// prepareReceivedItem 构建场景：上一班 S001（已结束）建立事项，经 H001 确认
28	// 接收到仍在进行中的下一班 S002；事项处理经过为建立与接收，四项信息齐全
29	// （限制条件非空）。返回场景事实与确认接收时刻。
30	func prepareReceivedItem(t *testing.T, f *fixture) updateScenario {
31		t.Helper()
32		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
33		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
34		it, err := f.svc.AddItem(a.ID, "原内容：一号泵压力异常", SeverityNormal, "原限制条件：需停电窗口", "李四")
35		if err != nil {
36			t.Fatalf("add item: %v", err)
37		}
38		if _, err := f.svc.CloseShift(a.ID); err != nil {
39			t.Fatalf("close from shift: %v", err)
40		}
41		h, err := f.svc.CreateHandover(a.ID, b.ID)
42		if err != nil {
43			t.Fatalf("create handover: %v", err)
44		}
45		confirmAt := tsDay(2, 17, 0)
46		f.svc.nowAt(func() time.Time { return confirmAt })
47		if _, err := f.svc.ProcessEntry(h.ID, it.ID, ActionConfirm, "李四", "", "", ""); err != nil {
48			t.Fatalf("confirm receive: %v", err)
49		}
50		return updateScenario{
51			shiftFrom: a.ID, shiftTo: b.ID, handoverID: h.ID, itemID: it.ID,
52			oldContent: "原内容：一号泵压力异常", oldSeverity: SeverityNormal,
53			oldConstraints: "原限制条件：需停电窗口", oldFollow: "李四",
54			newContent: "新内容：一号泵压力已复核", newSeverity: SeverityUrgent,
55			newConstraints: "新限制条件：夜间禁动", newFollow: "王五",
56		}
57	}
58	
59	func itemEventKinds(it Item) []string {
60		kinds := []string{}
61		for _, ev := range it.Events {
62			kinds = append(kinds, ev.Kind)
63		}
64		return kinds
65	}
66	
67	// assertUpdateRolledBack 用当前打开的数据核对：失败的修改没有留下任何一部分，
68	// 系统里仍是失败前已保存的全部信息。
69	func assertUpdateRolledBack(t *testing.T, f *fixture, sc updateScenario, confirmAt time.Time) {
70		t.Helper()
71	
72		// 单项查询：四项信息仍是失败前的值——不能出现内容已变而负责人未变、
73		// 或原限制条件被清空这类半完成状态；编号、原始班次、当前班次、流经班次
74		// 与未关闭状态保持原样。
75		it, err := f.svc.GetItem(sc.itemID)
76		if err != nil {
77			t.Fatalf("get item: %v", err)
78		}
79		if it.ID != sc.itemID || it.OriginShiftID != sc.shiftFrom || it.CurrentShiftID != sc.shiftTo {
80			t.Fatalf("事项编号与所在班次应保持原样：%+v", it)
81		}
82		if joinStrings(it.ShiftIDs) != sc.shiftFrom+","+sc.shiftTo {
83			t.Fatalf("流经班次应保持原样：%v", it.ShiftIDs)
84		}
85		if it.Closed || it.ClosedAt != nil {
86			t.Fatalf("事项应保持未关闭：%+v", it)
87		}
88		if it.Content != sc.oldContent || it.Severity != sc.oldSeverity ||
89			it.Constraints != sc.oldConstraints || it.FollowOwner != sc.oldFollow {
90			t.Fatalf("保存失败后四项信息应全部保持失败前的值：%+v", it)
91		}
92		// 处理经过保留此前的建立与接收，不新增这次失败的修改记录，也不丢失原有记录。
93		if got := joinStrings(itemEventKinds(it)); got != "created,received" {
94			t.Fatalf("事项处理经过应仍只有建立与接收，got %s", got)
95		}
96	
97		// 处理经过查询与单项查询一致，交接当前结果仍是当时的确认接收。
98		j, err := f.svc.ItemJourney(sc.itemID)
99		if err != nil {
100			t.Fatalf("journey: %v", err)
101		}
102		if j.Item.Content != sc.oldContent || j.Item.Constraints != sc.oldConstraints ||
103			j.Item.FollowOwner != sc.oldFollow || j.Item.Severity != sc.oldSeverity {
104			t.Fatalf("处理经过中的最新状态应与失败前一致：%+v", j.Item)
105		}
106		if got := joinStrings(journeyKinds(j)); got != "created,handover-init,confirm" {
107			t.Fatalf("处理经过不应出现失败的修改记录，got %s", got)
108		}
109		if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryConfirmed ||
110			j.Results[0].Entry.Operator != "李四" ||
111			j.Results[0].Entry.ProcessedAt == nil || !j.Results[0].Entry.ProcessedAt.Equal(confirmAt) {
112			t.Fatalf("交接当前结果应仍为当时的确认接收：%+v", j.Results)
113		}
114	
115		// 交接记录：确认接收结果、处理人和处理时间不受修改失败影响；
116		// 清单里保存的事项原文不被改动。
117		h, err := f.svc.GetHandover(sc.handoverID)
118		if err != nil {
119			t.Fatalf("get handover: %v", err)
120		}
121		e := findEntryOf(t, h, sc.itemID)
122		if e.Status != EntryConfirmed || e.Operator != "李四" ||
123			e.ProcessedAt == nil || !e.ProcessedAt.Equal(confirmAt) {
124			t.Fatalf("交接中的确认接收结果应保持原样：%+v", e)
125		}
126		if e.Content != sc.oldContent || e.Constraints != sc.oldConstraints || e.FollowOwner != sc.oldFollow {
127			t.Fatalf("交接清单保存的事项原文不应被改动：%+v", e)
128		}
129	
130		// 当前班次报告中的事项信息与单项查询一致（仍是失败前的值）。
131		repB, err := f.svc.ShiftReport(sc.shiftTo)
132		if err != nil {
133			t.Fatalf("report current shift: %v", err)
134		}
135		cur := []Item{}
136		for _, x := range repB.Items {
137			if x.ID == sc.itemID {
138				cur = append(cur, x)
139			}
140		}
141		if len(cur) != 1 || cur[0].Content != sc.oldContent || cur[0].Severity != sc.oldSeverity ||
142			cur[0].Constraints != sc.oldConstraints || cur[0].FollowOwner != sc.oldFollow {
143			t.Fatalf("当前班次报告应与单项查询一致（失败前的值）：%+v", cur)
144		}
145	
146		// 上一班的结束时记录继续保留当时的内容、严重程度、限制条件和负责人。
147		repA, err := f.svc.ShiftReport(sc.shiftFrom)
148		if err != nil {
149			t.Fatalf("report from shift: %v", err)
150		}
151		if !repA.ItemsAtClose {
152			t.Fatalf("上一班已结束，应展示结束时记录")
153		}
154		snap := findCloseItem(repA, sc.itemID)
155		if snap == nil || snap.Content != sc.oldContent || snap.Severity != sc.oldSeverity ||
156			snap.Constraints != sc.oldConstraints || snap.FollowOwner != sc.oldFollow {
157			t.Fatalf("上一班结束时记录应保持当时的四项信息：%+v", snap)
158		}
159	}
160	
161	// assertUpdateSucceeded 核对恢复保存后的那次成功修改：四项新信息生效、
162	// 新增一次修改经过且发生时间属于成功操作，历史记录各自保留原含义。
163	func assertUpdateSucceeded(t *testing.T, f *fixture, sc updateScenario, confirmAt, successAt time.Time) {
164		t.Helper()
165	
166		it, err := f.svc.GetItem(sc.itemID)
167		if err != nil {
168			t.Fatalf("get item: %v", err)
169		}
170		if it.Content != sc.newContent || it.Severity != sc.newSeverity ||
171			it.Constraints != sc.newConstraints || it.FollowOwner != sc.newFollow {
172			t.Fatalf("成功后查询应展示四项新信息：%+v", it)
173		}
174		if it.ID != sc.itemID || it.OriginShiftID != sc.shiftFrom || it.CurrentShiftID != sc.shiftTo ||
175			joinStrings(it.ShiftIDs) != sc.shiftFrom+","+sc.shiftTo || it.Closed {
176			t.Fatalf("编号、原始班次、当前班次、流经班次与未关闭状态不应被修改改变：%+v", it)
177		}
178		// 新增一次对应的修改经过，发生时间属于这次成功操作，不能沿用失败时刻。
179		if got := joinStrings(itemEventKinds(it)); got != "created,received,updated" {
180			t.Fatalf("成功后应只新增一次修改经过，got %s", got)
181		}
182		up := it.Events[len(it.Events)-1]
183		if !up.At.Equal(successAt) {
184			t.Fatalf("修改经过的发生时间应属于成功操作 %s，got %s", successAt, up.At)
185		}
186	
187		j, err := f.svc.ItemJourney(sc.itemID)
188		if err != nil {
189			t.Fatalf("journey: %v", err)
190		}
191		if got := joinStrings(journeyKinds(j)); got != "created,handover-init,confirm,updated" {
192			t.Fatalf("处理经过应新增一次修改，got %s", got)
193		}
194		updated := 0
195		for _, ev := range j.Events {
196			if ev.Kind == "updated" {
197				updated++
198				if !ev.TimeKnown || !ev.At.Equal(successAt) {
199					t.Fatalf("修改经过时间应为成功操作时刻：%+v", ev)
200				}
201			}
202		}
203		if updated != 1 {
204			t.Fatalf("处理经过应只新增一次修改记录，got %d", updated)
205		}
206	
207		// 最新负责人和接收当时的处理信息各自保留自己的含义：交接清单里的
208		// 确认接收结果、处理人、处理时间与事项原文不被新值替换。
209		h, err := f.svc.GetHandover(sc.handoverID)
210		if err != nil {
211			t.Fatalf("get handover: %v", err)
212		}
213		e := findEntryOf(t, h, sc.itemID)
214		if e.Status != EntryConfirmed || e.Operator != "李四" ||
215			e.ProcessedAt == nil || !e.ProcessedAt.Equal(confirmAt) {
216			t.Fatalf("接收当时的处理信息应保持原样：%+v", e)
217		}
218		if e.Content != sc.oldContent || e.Constraints != sc.oldConstraints || e.FollowOwner != sc.oldFollow {
219			t.Fatalf("交接中的事项原文不能被新值替换：%+v", e)
220		}
221		if h.CompletedAt == nil || !h.CompletedAt.Equal(confirmAt) {
222			t.Fatalf("交接完成时间应保持接收齐的时刻：%+v", h.CompletedAt)
223		}
224	
225		// 上一班结束时记录继续保留当时的四项信息。
226		repA, err := f.svc.ShiftReport(sc.shiftFrom)
227		if err != nil {
228			t.Fatalf("report from shift: %v", err)
229		}
230		snap := findCloseItem(repA, sc.itemID)
231		if snap == nil || snap.Content != sc.oldContent || snap.Severity != sc.oldSeverity ||
232			snap.Constraints != sc.oldConstraints || snap.FollowOwner != sc.oldFollow {
233			t.Fatalf("上一班结束时记录不应被新值替换：%+v", snap)
234		}
235	
236		// 当前班次报告展示修改后的新值，与单项查询一致。
237		repB, err := f.svc.ShiftReport(sc.shiftTo)
238		if err != nil {
239			t.Fatalf("report current shift: %v", err)
240		}
241		cur := []Item{}
242		for _, x := range repB.Items {
243			if x.ID == sc.itemID {
244				cur = append(cur, x)
245			}
246		}
247		if len(cur) != 1 || cur[0].Content != sc.newContent || cur[0].Severity != sc.newSeverity ||
248			cur[0].Constraints != sc.newConstraints || cur[0].FollowOwner != sc.newFollow {
249			t.Fatalf("当前班次报告应展示修改后的四项新信息：%+v", cur)
250		}
251	}
252	
253	// TestUpdateSaveFailureAtomicRollback：接班人在当前班次对已接收事项同时修改
254	// 内容、严重程度、限制条件和后续负责人，参数合法、状态允许、真正进入保存过程
255	// 后本地写盘失败——操作必须明确返回保存错误、不把未保存的新值当作修改结果；
256	// 凭编号查询仍是失败前的全部信息，处理经过、当前班次报告、上一班结束时记录
257	// 与交接接收结果都不变，数据文件一个字节不动，重新打开后一致。保存恢复后对
258	// 同一事项再次提交同样的修改应成功，且只留下成功这一次修改经过。
259	func TestUpdateSaveFailureAtomicRollback(t *testing.T) {
260		f := newFixture(t)
261		sc := prepareReceivedItem(t, f)
262		confirmAt := tsDay(2, 17, 0)
263	
264		// 记录失败前已落盘的文件内容，并固定失败尝试的发生时刻。
265		rawBefore, err := os.ReadFile(f.store.Path())
266		if err != nil {
267			t.Fatalf("read data file: %v", err)
268		}
269		failAt := tsDay(2, 18, 0)
270		f.svc.nowAt(func() time.Time { return failAt })
271	
272		// 使下一次写盘在原子保存阶段失败，然后同时修改四项信息。
273		breakSaving(t, f)
274		got, err := f.svc.UpdateItem(sc.itemID, sc.newContent, sc.newSeverity, sc.newConstraints, sc.newFollow)
275		// 操作输出必须明确报错：这是保存错误而不是业务拒绝（不能用内容为空、
276		// 班次已结束等来冒充），也不能把尚未保存的新值当作修改结果返回。
277		if err == nil {
278			t.Fatalf("保存失败时修改应返回错误")
279		}
280		if !strings.Contains(err.Error(), "写入数据文件失败") {
281			t.Fatalf("应明确返回保存阶段的错误，got %v", err)
282		}
283		if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrShiftClosed) || errors.Is(err, ErrNotFound) {
284			t.Fatalf("参数合法、状态允许时的保存失败不应被报告为业务校验错误，got %v", err)
285		}
286		if !reflect.DeepEqual(got, Item{}) {
287			t.Fatalf("保存失败不得把尚未保存的新值当作修改结果返回：%+v", got)
288		}
289	
290		// 当前打开的数据中不留这次修改的任何一部分。
291		assertUpdateRolledBack(t, f, sc, confirmAt)
292	
293		// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
294		rawAfter, err := os.ReadFile(f.store.Path())
295		if err != nil {
296			t.Fatalf("read data file after failure: %v", err)
297		}
298		if string(rawAfter) != string(rawBefore) {
299			t.Fatalf("保存失败不得改动既有数据文件")
300		}
301	
302		// 在失败之后、成功之前退出并重新打开：仍应看到原来已保存的事项与历史。
303		f.reopen(t)
304		assertUpdateRolledBack(t, f, sc, confirmAt)
305	
306		// 恢复正常保存后，对同一事项再次提交同样的修改应能成功。
307		restoreSaving(t, f)
308		successAt := tsDay(2, 19, 0)
309		f.svc.nowAt(func() time.Time { return successAt })
310		updated, err := f.svc.UpdateItem(sc.itemID, sc.newContent, sc.newSeverity, sc.newConstraints, sc.newFollow)
311		if err != nil {
312			t.Fatalf("恢复后修改应成功：%v", err)
313		}
314		if updated.Content != sc.newContent || updated.Severity != sc.newSeverity ||
315			updated.Constraints != sc.newConstraints || updated.FollowOwner != sc.newFollow {
316			t.Fatalf("成功修改的返回结果应为四项新信息：%+v", updated)
317		}
318		assertUpdateSucceeded(t, f, sc, confirmAt, successAt)
319	
320		// 退出后重新打开同一份数据，看到的应与最后一次成功保存后的查询一致。
321		f.reopen(t)
322		assertUpdateSucceeded(t, f, sc, confirmAt, successAt)
323	}
