1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	func requireNonEmpty(field, v string) error {
27		if clean(v) == "" {
28			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
29		}
30		return nil
31	}
32	
33	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
34		// 前班结束恰好等于后班开始（端点相等）不算重叠。
35		return s1.Before(e2) && s2.Before(e1)
36	}
37	
38	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
39	func notePair(a, b string) (string, string) {
40		if a <= b {
41			return a, b
42		}
43		return b, a
44	}
45	
46	func findShift(d *Data, id string) (*Shift, int) {
47		for i := range d.Shifts {
48			if d.Shifts[i].ID == id {
49				return &d.Shifts[i], i
50			}
51		}
52		return nil, -1
53	}
54	
55	func findItem(d *Data, id string) (*Item, int) {
56		for i := range d.Items {
57			if d.Items[i].ID == id {
58				return &d.Items[i], i
59			}
60		}
61		return nil, -1
62	}
63	
64	func findHandover(d *Data, id string) (*Handover, int) {
65		for i := range d.Handovers {
66			if d.Handovers[i].ID == id {
67				return &d.Handovers[i], i
68			}
69		}
70		return nil, -1
71	}
72	
73	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
74		for i := range h.Entries {
75			if h.Entries[i].ItemID == itemID {
76				return &h.Entries[i], i
77			}
78		}
79		return nil, -1
80	}
81	
82	func findNote(d *Data, a, b string) *OverlapNote {
83		x, y := notePair(a, b)
84		for i := range d.Notes {
85			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
86				return &d.Notes[i]
87			}
88		}
89		return nil
90	}
91	
92	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
93	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
94	func currentItemsOfShift(d *Data, shiftID string) []Item {
95		out := []Item{}
96		seen := map[string]bool{}
97		for _, it := range d.Items {
98			if seen[it.ID] {
99				continue
100			}
101			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
102				seen[it.ID] = true
103				out = append(out, it)
104			}
105		}
106		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
107		return out
108	}
109	
110	func hasNote(d *Data, a, b string) bool { return findNote(d, a, b) != nil }
111	
112	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
113	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
114	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
115	// 不同岗位互不影响。
116	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
117		position = clean(position)
118		owner = clean(owner)
119		overlapNote = clean(overlapNote)
120		if err := requireNonEmpty("岗位", position); err != nil {
121			return Shift{}, err
122		}
123		if err := requireNonEmpty("负责人", owner); err != nil {
124			return Shift{}, err
125		}
126		if !end.After(start) {
127			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
128				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
129		}
130	
131		var created Shift
132		err := svc.store.mutate(func(d *Data) error {
133			var overlapping []Shift
134			for _, sh := range d.Shifts {
135				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
136					overlapping = append(overlapping, sh)
137				}
138			}
139			if len(overlapping) > 0 && overlapNote == "" {
140				ids := make([]string, len(overlapping))
141				for i, sh := range overlapping {
142					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
143				}
144				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
145					ErrOverlap, strings.Join(ids, "、"))
146			}
147	
148			d.ShiftSeq++
149			now := svc.now()
150			created = Shift{
151				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
152				Position:  position,
153				Owner:     owner,
154				Start:     start,
155				End:       end,
156				CreatedAt: now,
157			}
158			d.Shifts = append(d.Shifts, created)
159	
160			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
161			for _, sh := range overlapping {
162				if findNote(d, created.ID, sh.ID) != nil {
163					continue
164				}
165				d.NoteSeq++
166				x, y := notePair(created.ID, sh.ID)
167				d.Notes = append(d.Notes, OverlapNote{
168					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
169					Position:  position,
170					ShiftA:    x,
171					ShiftB:    y,
172					Note:      overlapNote,
173					CreatedAt: now,
174				})
175			}
176			return nil
177		})
178		return created, err
179	}
180	
181	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
182	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
183		note = clean(note)
184		if err := requireNonEmpty("重叠说明", note); err != nil {
185			return OverlapNote{}, err
186		}
187		if clean(shiftA) == clean(shiftB) {
188			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
189		}
190	
191		var saved OverlapNote
192		err := svc.store.mutate(func(d *Data) error {
193			sa, _ := findShift(d, clean(shiftA))
194			sb, _ := findShift(d, clean(shiftB))
195			if sa == nil || sb == nil {
196				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
197			}
198			if sa.Position != sb.Position {
199				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
200					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
201			}
202			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
203				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
204					ErrInvalidInput, sa.ID, sb.ID)
205			}
206			d.NoteSeq++
207			x, y := notePair(sa.ID, sb.ID)
208			saved = OverlapNote{
209				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
210				Position:  sa.Position,
211				ShiftA:    x,
212				ShiftB:    y,
213				Note:      note,
214				CreatedAt: svc.now(),
215			}
216			d.Notes = append(d.Notes, saved)
217			return nil
218		})
219		return saved, err
220	}
221	
222	// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
223	func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
224		shiftID = clean(shiftID)
225		content = clean(content)
226		constraints = clean(constraints)
227		followOwner = clean(followOwner)
228		if err := requireNonEmpty("事项内容", content); err != nil {
229			return Item{}, err
230		}
231		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
232			return Item{}, err
233		}
234		if !severity.valid() {
235			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
236		}
237	
238		var created Item
239		err := svc.store.mutate(func(d *Data) error {
240			sh, _ := findShift(d, shiftID)
241			if sh == nil {
242				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
243			}
244			if sh.Closed {
245				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
246			}
247			d.ItemSeq++
248			now := svc.now()
249			created = Item{
250				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
251				OriginShiftID:  sh.ID,
252				ShiftIDs:       []string{sh.ID},
253				CurrentShiftID: sh.ID,
254				Content:        content,
255				Severity:       severity,
256				Constraints:    constraints,
257				FollowOwner:    followOwner,
258				CreatedAt:      now,
259				Events: []ItemEvent{
260					{At: now, Kind: "created", Detail: "事项建立"},
261				},
262			}
263			d.Items = append(d.Items, created)
264			return nil
265		})
266		return created, err
267	}
268	
269	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
270	// 只有本地数据保存成功才算修改完成：写盘失败时内存变更随快照一并回滚，
271	// 返回错误与零值事项，不把尚未保存的新值当作修改结果。
272	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
273		itemID = clean(itemID)
274		content = clean(content)
275		constraints = clean(constraints)
276		followOwner = clean(followOwner)
277		if err := requireNonEmpty("事项内容", content); err != nil {
278			return Item{}, err
279		}
280		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
281			return Item{}, err
282		}
283		if !severity.valid() {
284			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
285		}
286	
287		var updated Item
288		err := svc.store.mutate(func(d *Data) error {
289			it, _ := findItem(d, itemID)
290			if it == nil {
291				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
292			}
293			sh, _ := findShift(d, it.CurrentShiftID)
294			if sh == nil || sh.Closed {
295				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
296					ErrShiftClosed, itemID, it.CurrentShiftID)
297			}
298			changes := []string{}
299			if it.Content != content {
300				changes = append(changes, "内容")
301			}
302			if it.Severity != severity {
303				changes = append(changes, "严重程度")
304			}
305			if it.Constraints != constraints {
306				changes = append(changes, "限制条件")
307			}
308			if it.FollowOwner != followOwner {
309				changes = append(changes, "后续负责人")
310			}
311			it.Content = content
312			it.Severity = severity
313			it.Constraints = constraints
314			it.FollowOwner = followOwner
315			it.Events = append(it.Events, ItemEvent{
316				At:     svc.now(),
317				Kind:   "updated",
318				Detail: "修改字段：" + joinOr(changes, "无变更"),
319			})
320			updated = *it
321			return nil
322		})
323		if err != nil {
324			// 保存失败时内存已回滚，不能把尚未保存的新值当作修改结果返回。
325			return Item{}, err
326		}
327		return updated, nil
328	}
329	
330	func joinOr(xs []string, or string) string {
331		if len(xs) == 0 {
332			return or
333		}
334		return strings.Join(xs, "、")
335	}
336	
337	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
338	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
339		itemID = clean(itemID)
340		operator = clean(operator)
341		if err := requireNonEmpty("操作人", operator); err != nil {
342			return Item{}, err
343		}
344	
345		var closed Item
346		err := svc.store.mutate(func(d *Data) error {
347			it, _ := findItem(d, itemID)
348			if it == nil {
349				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
350			}
351			if it.Closed {
352				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
353			}
354			sh, _ := findShift(d, it.CurrentShiftID)
355			if sh == nil || sh.Closed {
356				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
357					ErrShiftClosed, itemID, it.CurrentShiftID)
358			}
359			now := svc.now()
360			it.Closed = true
361			it.ClosedAt = &now
362			it.CloseOperator = operator
363			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
364			closed = *it
365			return nil
366		})
367		return closed, err
368	}
369	
370	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
371	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
372	// 交接视为已完成，可以结束。
373	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
374	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
375	// 事项归属与已保存的处理经过。
376	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
377		shiftID = clean(shiftID)
378		var result Shift
379		err := svc.store.mutate(func(d *Data) error {
380			sh, _ := findShift(d, shiftID)
381			if sh == nil {
382				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
383			}
384			if sh.Closed {
385				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
386			}
387			for i := range d.Handovers {
388				h := &d.Handovers[i]
389				if h.ToShiftID == sh.ID && !h.Completed() {
390					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
391						ErrHandoverState, h.ID)
392				}
393			}
394			now := svc.now()
395			sh.Closed = true
396			sh.ClosedAt = &now
397	
398			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
399			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。
400			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
401			for i := range d.Items {
402				it := &d.Items[i]
403				if it.CurrentShiftID != sh.ID {
404					continue
405				}
406				record.Items = append(record.Items, CloseItemSnapshot{
407					ItemID:        it.ID,
408					Content:       it.Content,
409					Severity:      it.Severity,
410					Constraints:   it.Constraints,
411					FollowOwner:   it.FollowOwner,
412					Closed:        it.Closed,
413					ClosedAt:      it.ClosedAt,
414					CloseOperator: it.CloseOperator,
415				})
416			}
417			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
418			sh.CloseRecord = record
419	
420			result = *sh
421			return nil
422		})
423		return result, err
424	}
425	
426	// CreateHandover 由交班班次向同岗位接班班次发起交接。
427	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
428	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
429	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
430	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
431	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
432	// 要求仅对首次发起生效。
433	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
434		fromShiftID = clean(fromShiftID)
435		toShiftID = clean(toShiftID)
436	
437		var result Handover
438		err := svc.store.mutate(func(d *Data) error {
439			from, _ := findShift(d, fromShiftID)
440			to, _ := findShift(d, toShiftID)
441			if from == nil {
442				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
443			}
444			if to == nil {
445				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
446			}
447			if from.ID == to.ID {
448				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
449			}
450			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
451			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
452			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
453			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
454			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
455			// 存在与交给自身的校验仍在其前。
456			for i := range d.Handovers {
457				if d.Handovers[i].FromShiftID == from.ID {
458					existing := &d.Handovers[i]
459					result = *existing
460					if existing.ToShiftID != to.ID {
461						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
462							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
463					}
464					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
465				}
466			}
467	
468			if from.Position != to.Position {
469				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
470					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
471			}
472	
473			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
474			// 交班班次已经结束，重叠区间须有说明。
475			if to.Closed {
476				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
477			}
478			if to.Start.Before(from.Start) {
479				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
480					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
481					from.ID, from.Start.Format(time.RFC3339))
482			}
483			if !from.Closed {
484				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
485					ErrShiftNotClosed, from.ID)
486			}
487			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
488				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
489					ErrOverlap, from.ID, to.ID)
490			}
491	
492			entries := []HandoverEntry{}
493			for i := range d.Items {
494				it := &d.Items[i]
495				if it.CurrentShiftID == from.ID && !it.Closed {
496					entries = append(entries, HandoverEntry{
497						ItemID:      it.ID,
498						Content:     it.Content,
499						Severity:    it.Severity,
500						Constraints: it.Constraints,
501						FollowOwner: it.FollowOwner,
502						Status:      EntryPending,
503					})
504				}
505			}
506			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
507	
508			d.HandoverSeq++
509			now := svc.now()
510			h := Handover{
511				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
512				Position:    from.Position,
513				FromShiftID: from.ID,
514				ToShiftID:   to.ID,
515				CreatedAt:   now,
516				Entries:     entries,
517			}
518			if len(entries) == 0 {
519				// 空清单直接完成。
520				h.CompletedAt = &now
521			}
522			d.Handovers = append(d.Handovers, h)
523			result = h
524			return nil
525		})
526		return result, err
527	}
