529	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
530	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
531	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
532	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
533	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
534	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
535	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
536	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
537		handoverID = clean(handoverID)
538		itemID = clean(itemID)
539		operator = clean(operator)
540		reason = clean(reason)
541		trackingNote = clean(trackingNote)
542		nextFollowOwner = clean(nextFollowOwner)
543	
544		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
545			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
546		}
547		if err := requireNonEmpty("操作人", operator); err != nil {
548			return Handover{}, err
549		}
550	
551		var result Handover
552		err := svc.store.mutate(func(d *Data) error {
553			h, _ := findHandover(d, handoverID)
554			if h == nil {
555				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
556			}
557			e, _ := findEntry(h, itemID)
558			if e == nil {
559				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
560			}
561			if e.Status.Received() {
562				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
563					ErrHandoverState, e.ItemID, e.Status.Label())
564			}
565			if e.Status == EntryReturned {
566				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
567				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
568				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
569				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
570					ErrHandoverState, e.ItemID, h.ID)
571			}
572			switch action {
573			case ActionReturn:
574				if err := requireNonEmpty("退回原因", reason); err != nil {
575					return err
576				}
577			case ActionTrack:
578				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
579					return err
580				}
581				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
582					return err
583				}
584			}
585	
586			now := svc.now()
587			switch action {
588			case ActionConfirm:
589				e.Status = EntryConfirmed
590			case ActionTrack:
591				e.Status = EntryTracking
592				e.TrackingNote = trackingNote
593				e.FollowOwner = nextFollowOwner
594			case ActionReturn:
595				e.Status = EntryReturned
596				e.Rounds = append(e.Rounds, ReturnRound{
597					Seq:            len(e.Rounds) + 1,
598					ReturnedAt:     now,
599					ReturnOperator: operator,
600					Reason:         reason,
601				})
602			}
603			e.Operator = operator
604			e.ProcessedAt = &now
605	
606			if action != ActionReturn {
607				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
608				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
609					it.CurrentShiftID = h.ToShiftID
610					if !contains(it.ShiftIDs, h.ToShiftID) {
611						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
612					}
613					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
614					if action == ActionTrack {
615						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
616						it.FollowOwner = nextFollowOwner
617					}
618					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
619				}
620			}
621	
622			if h.Completed() {
623				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
624				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
625				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
626				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
627				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
628				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
629				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
630				// 项无法再处理，完成时间不会被改写。
631				h.CompletedAt = &now
632			}
633			result = *h
634			return nil
635		})
636		return result, err
637	}
638	
639	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
640	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
641	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
642	
643	func contains(xs []string, x string) bool {
644		for _, v := range xs {
645			if v == x {
646				return true
647			}
648		}
649		return false
650	}
651	
652	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
653	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
654	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
655	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
656	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
657	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
658	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
659		handoverID = clean(handoverID)
660		itemID = clean(itemID)
661		operator = clean(operator)
662		supplement = clean(supplement)
663		if err := requireNonEmpty("操作人", operator); err != nil {
664			return Handover{}, err
665		}
666		if err := requireNonEmpty("补充说明", supplement); err != nil {
667			return Handover{}, err
668		}
669	
670		var result Handover
671		err := svc.store.mutate(func(d *Data) error {
672			h, _ := findHandover(d, handoverID)
673			if h == nil {
674				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
675			}
676			e, _ := findEntry(h, itemID)
677			if e == nil {
678				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
679			}
680			if e.Status != EntryReturned {
681				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
682					ErrHandoverState, e.ItemID, e.Status.Label())
683			}
684			if len(e.Rounds) == 0 {
685				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
686			}
687			round := &e.Rounds[len(e.Rounds)-1]
688			if round.ResubmittedAt != nil {
689				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
690			}
691			now := svc.now()
692			round.Supplement = supplement
693			round.SupplementOperator = operator
694			round.SupplementAt = &now
695			round.ResubmittedAt = &now
696			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
697			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
698			e.Status = EntryPending
699			e.Operator = ""
700			e.ProcessedAt = nil
701			result = *h
702			return nil
703		})
704		return result, err
705	}
