732	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
733	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
734	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
735	// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
736	// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
737	// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
738	// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
739	// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
740	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
741	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
742	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
743	// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
744	// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
745	// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
746	// 不改变事项、交接进度或班次结束时记录。
747	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
748		itemID = clean(itemID)
749		d := &svc.store.data
750		it, _ := findItem(d, itemID)
751		if it == nil {
752			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
753		}
754		j := ItemJourney{Item: *it}
755	
756		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
757		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
758		// 该轮重新提交、后续处理）。
759		type keyedEvent struct {
760			ev    JourneyEvent
761			group string // "" 表示事项自身事件，否则为交接编号
762			ord   int    // 同一（时刻、分组）内的先后
763		}
764		var events []keyedEvent
765		seq := 0
766		add := func(ev JourneyEvent, group string) {
767			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
768			seq++
769		}
770	
771		// 接收记录的合并判定集中在 receivedMerge（见 received_merge.go）：遍历各次
772		// 交接清单时标记与某次接收同属一次的事项 received 事件，该事件随后只以信息
773		// 更全的交接事件展示。未标记的 received 事件（缺交接编号或交班班次的旧
774		// 说明、指向其他交接/班次/方式的说明、自由文字或残缺说明等）在下面原样保留。
775		merge := newReceivedMerge(it.Events)
776	
777		hs := append([]Handover(nil), d.Handovers...)
778		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
779		for k := range hs {
780			h := &hs[k]
781			e, _ := findEntry(h, itemID)
782			if e == nil {
783				continue
784			}
785			j.HasHandovers = true
786			j.Results = append(j.Results, EntryView{
787				HandoverID: h.ID,
788				FromShift:  h.FromShiftID,
789				ToShift:    h.ToShiftID,
790				Entry:      *e,
791			})
792	
793			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
794			add(JourneyEvent{
795				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
796				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
797			}, h.ID)
798			for _, r := range e.Rounds {
799				add(JourneyEvent{
800					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
801					Kind: "return", Operator: r.ReturnOperator,
802					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
803					RoundSeq: r.Seq, Reason: r.Reason,
804				}, h.ID)
805				if r.ResubmittedAt != nil {
806					add(JourneyEvent{
807						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
808						Kind: "resubmit", Operator: r.SupplementOperator,
809						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
810						RoundSeq: r.Seq, Supplement: r.Supplement,
811						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
812					}, h.ID)
813				}
814			}
815			if e.Status == EntryReturned && len(e.Rounds) == 0 {
816				// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
817				// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
818				// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
819				// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
820				// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
821				ev := JourneyEvent{
822					Kind: "return-incomplete", Operator: e.Operator,
823					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
824					HistoryIncomplete: true,
825				}
826				if validProcessedAt(e.ProcessedAt) {
827					ev.At, ev.TimeKnown = *e.ProcessedAt, true
828				}
829				add(ev, h.ID)
830			}
831			if e.Status.Received() {
832				rcpt := receiptFromEntry(h, e)
833				ev := JourneyEvent{
834					Kind: rcpt.kind, Operator: e.Operator,
835					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
836					TrackingNote: e.TrackingNote,
837					// 继续跟踪当时指定的后续负责人取自交接记录快照，
838					// 之后修改事项负责人不改变这里的历史值。
839					FollowOwner: e.FollowOwner,
840				}
841				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
842				// 时间标为未记录，排在有真实时间的事件之后；这种凭据 timeKnown
843				// 为 false，consider 不会合并任何事项事件（也不拿发起时间代替）。
844				if rcpt.timeKnown {
845					ev.At, ev.TimeKnown = rcpt.at, true
846				}
847				add(ev, h.ID)
848				// 标记与本次接收同属一次的事项 received 事件；合并依据全部在
849				// sameReceivedEvent 中：操作人与实际时刻相同，且说明完整记载
850				// 交接编号、交班、接班班次与接收方式并逐项一致。缺归属信息的
851				// 旧说明、残缺或自由文字说明一律不合并，原样作为独立接收历史。
852				merge.consider(rcpt)
853			}
854		}
855	
856		// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
857		// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
858		for i, iev := range it.Events {
859			if iev.Kind == "received" && merge.isUsed(i) {
860				continue
861			}
862			add(JourneyEvent{
863				At: iev.At, TimeKnown: !iev.At.IsZero(),
864				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
865			}, "")
866		}
867	
868		sort.SliceStable(events, func(i, k int) bool {
869			a, b := events[i], events[k]
870			if a.ev.TimeKnown != b.ev.TimeKnown {
871				return a.ev.TimeKnown
872			}
873			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
874				return a.ev.At.Before(b.ev.At)
875			}
876			if a.group != b.group {
877				return a.group < b.group
878			}
879			return a.ord < b.ord
880		})
881		for _, ke := range events {
882			j.Events = append(j.Events, ke.ev)
883		}
884		return j, nil
885	}
