915	
916	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
917	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
918	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
919	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
920		shiftID = clean(shiftID)
921		d := &svc.store.data
922		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
923		sh, _ := findShift(d, shiftID)
924		if sh == nil {
925			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
926		}
927		rep.Shift = *sh
928	
929		for _, n := range d.Notes {
930			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
931				rep.OverlapNotes = append(rep.OverlapNotes, n)
932			}
933		}
934		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
935	
936		switch {
937		case !sh.Closed:
938			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
939			rep.Items = currentItemsOfShift(d, sh.ID)
940		case sh.CloseRecord != nil:
941			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
942			rep.ItemsAtClose = true
943			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
944			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
945			for _, s := range rep.CloseItems {
946				if it, _ := findItem(d, s.ItemID); it != nil {
947					rep.LatestItems[s.ItemID] = *it
948				}
949			}
950		default:
951			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
952			rep.HistoryIncomplete = true
953			rep.Items = currentItemsOfShift(d, sh.ID)
954		}
955		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
956	
957		for i := range d.Handovers {
958			h := &d.Handovers[i]
959			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
960			if !involved {
961				continue
962			}
963			if h.FromShiftID == sh.ID {
964				cp := *h
965				rep.Outgoing = &cp
966			}
967			if h.ToShiftID == sh.ID {
968				rep.Incoming = append(rep.Incoming, *h)
969			}
970			for j := range h.Entries {
971				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
972					HandoverID: h.ID,
973					FromShift:  h.FromShiftID,
974					ToShift:    h.ToShiftID,
975					Entry:      h.Entries[j],
976				})
977			}
978		}
979		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
980		for k := range rep.Results {
981			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
982		}
983		return rep, nil
984	}
