// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
// 不改变事项、交接进度或班次结束时记录。
func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
	itemID = clean(itemID)
	d := &svc.store.data
	it, _ := findItem(d, itemID)
	if it == nil {
		return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
	}
	j := ItemJourney{Item: *it}

	// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
	// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
	// 该轮重新提交、后续处理）。
	type keyedEvent struct {
		ev    JourneyEvent
		group string // "" 表示事项自身事件，否则为交接编号
		ord   int    // 同一（时刻、分组）内的先后
	}
	var events []keyedEvent
	seq := 0
	add := func(ev JourneyEvent, group string) {
		events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
		seq++
	}

	// 接收记录的合并判定集中在 receivedMerge（见 received_merge.go）：遍历各次
	// 交接清单时标记与某次接收同属一次的事项 received 事件，该事件随后只以信息
	// 更全的交接事件展示。未标记的 received 事件（缺交接编号或交班班次的旧
	// 说明、指向其他交接/班次/方式的说明、自由文字或残缺说明等）在下面原样保留。
	merge := newReceivedMerge(it.Events)

	hs := append([]Handover(nil), d.Handovers...)
	sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
	for k := range hs {
		h := &hs[k]
		e, _ := findEntry(h, itemID)
		if e == nil {
			continue
		}
		j.HasHandovers = true
		j.Results = append(j.Results, EntryView{
			HandoverID: h.ID,
			FromShift:  h.FromShiftID,
			ToShift:    h.ToShiftID,
			Entry:      *e,
		})

		// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
		add(JourneyEvent{
			At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
			Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
		}, h.ID)
		for _, r := range e.Rounds {
			add(JourneyEvent{
				At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
				Kind: "return", Operator: r.ReturnOperator,
				HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
				RoundSeq: r.Seq, Reason: r.Reason,
			}, h.ID)
			if r.ResubmittedAt != nil {
				add(JourneyEvent{
					At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
					Kind: "resubmit", Operator: r.SupplementOperator,
					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
					RoundSeq: r.Seq, Supplement: r.Supplement,
					SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
				}, h.ID)
			}
		}
		if e.Status == EntryReturned && len(e.Rounds) == 0 {
			// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
			// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
			// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
			// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
			// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
			ev := JourneyEvent{
				Kind: "return-incomplete", Operator: e.Operator,
				HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
				HistoryIncomplete: true,
			}
			if validProcessedAt(e.ProcessedAt) {
				ev.At, ev.TimeKnown = *e.ProcessedAt, true
			}
			add(ev, h.ID)
		}
		if e.Status.Received() {
			rcpt := receiptFromEntry(h, e)
			ev := JourneyEvent{
				Kind: rcpt.kind, Operator: e.Operator,
				HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
				TrackingNote: e.TrackingNote,
				// 继续跟踪当时指定的后续负责人取自交接记录快照，
				// 之后修改事项负责人不改变这里的历史值。
				FollowOwner: e.FollowOwner,
			}
			// 处理时间缺失或为旧数据零值时仍保留该处理事件，
			// 时间标为未记录，排在有真实时间的事件之后；这种凭据 timeKnown
			// 为 false，consider 不会合并任何事项事件（也不拿发起时间代替）。
			if rcpt.timeKnown {
				ev.At, ev.TimeKnown = rcpt.at, true
			}
			add(ev, h.ID)
			// 标记与本次接收同属一次的事项 received 事件；合并依据全部在
			// sameReceivedEvent 中：操作人与实际时刻相同，且说明完整记载
			// 交接编号、交班、接班班次与接收方式并逐项一致。缺归属信息的
			// 旧说明、残缺或自由文字说明一律不合并，原样作为独立接收历史。
			merge.consider(rcpt)
		}
	}

	// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
	// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
	for i, iev := range it.Events {
		if iev.Kind == "received" && merge.isUsed(i) {
			continue
		}
		add(JourneyEvent{
			At: iev.At, TimeKnown: !iev.At.IsZero(),
			Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
		}, "")
	}

	sort.SliceStable(events, func(i, k int) bool {
		a, b := events[i], events[k]
		if a.ev.TimeKnown != b.ev.TimeKnown {
			return a.ev.TimeKnown
		}
		if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
			return a.ev.At.Before(b.ev.At)
		}
		if a.group != b.group {
			return a.group < b.group
		}
		return a.ord < b.ord
	})
	for _, ke := range events {
		j.Events = append(j.Events, ke.ev)
	}
	return j, nil
}

// GetHandover 按编号查询交接。
func (svc *Service) GetHandover(id string) (Handover, error) {
	h, _ := findHandover(&svc.store.data, clean(id))
	if h == nil {
		return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
	}
	return *h, nil
}

// ListHandovers 返回全部交接记录，按编号排序。
func (svc *Service) ListHandovers() []Handover {
	out := append([]Handover(nil), svc.store.data.Handovers...)
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// OverlapNotes 返回涉及指定班次的全部重叠说明。
func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
	shiftID = clean(shiftID)
	out := []OverlapNote{}
	for _, n := range svc.store.data.Notes {
		if n.ShiftA == shiftID || n.ShiftB == shiftID {
			out = append(out, n)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
	shiftID = clean(shiftID)
	d := &svc.store.data
	rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
	sh, _ := findShift(d, shiftID)
	if sh == nil {
		return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
	}
	rep.Shift = *sh

	for _, n := range d.Notes {
		if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
			rep.OverlapNotes = append(rep.OverlapNotes, n)
		}
	}
	sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })

	switch {
	case !sh.Closed:
		// 进行中的班次：事项可继续修改、关闭，展示当前信息。
		rep.Items = currentItemsOfShift(d, sh.ID)
	case sh.CloseRecord != nil:
		// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
		rep.ItemsAtClose = true
		rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
		sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
		for _, s := range rep.CloseItems {
			if it, _ := findItem(d, s.ItemID); it != nil {
				rep.LatestItems[s.ItemID] = *it
			}
		}
	default:
		// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
		rep.HistoryIncomplete = true
		rep.Items = currentItemsOfShift(d, sh.ID)
	}
	sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })

	for i := range d.Handovers {
		h := &d.Handovers[i]
		involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
		if !involved {
			continue
		}
		if h.FromShiftID == sh.ID {
			cp := *h
			rep.Outgoing = &cp
		}
		if h.ToShiftID == sh.ID {
			rep.Incoming = append(rep.Incoming, *h)
		}
		for j := range h.Entries {
			rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
				HandoverID: h.ID,
				FromShift:  h.FromShiftID,
				ToShift:    h.ToShiftID,
				Entry:      h.Entries[j],
			})
		}
	}
	sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
	for k := range rep.Results {
		sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
	}
	return rep, nil
}

package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// 本文件从用户实际使用命令行的角度，为“修改事项（item-update）在本地数据
// 保存阶段失败”建立端到端回归保障：上一班已结束、事项已确认接收到仍在进行
// 中的下一班，用户通过现有修改功能同时改动内容、严重程度、限制条件和后续
// 负责人四项，而数据文件的临时写入路径被占用（保存必然失败）。此时：
//   - 命令必须非零退出、错误输出明确是保存失败，正常输出为空——不显示
//     “已修改事项”的成功提示，也不展示尚未保存的新值；
//   - 数据文件一个字节不变；item-show、shift-show（当前班与上一班结束时
//     记录）、handover-show 都仍是失败前的全部信息，不出现内容已变而
//     负责人未变、原限制条件被清空这类半完成状态；
//   - 恢复保存后对同一事项再次提交同样的修改应成功，查询展示四项新信息，
//     而上一班结束时记录与交接清单中的事项原文不被新值替换。

// setupReceivedItemForUpdate 按用户真实步骤建立场景并返回数据文件路径：
// S001（张三，白班，已结束）-> S002（李四，夜班，进行中）；I001 在 S001 建立
// （内容、严重程度、非空限制条件、后续负责人齐全），经 H001 确认接收到 S002。
func setupReceivedItemForUpdate(t *testing.T) string {
	t.Helper()
	dataPath := filepath.Join(t.TempDir(), "handover-data.json")
	must := func(what string, r cliResult) {
		t.Helper()
		r.ok(t, what)
	}

	must("建立交班班次", runCLI(t, dataPath,
		"shift-add", "--position", "调度", "--owner", "张三",
		"--start", "2026-10-02T08:00:00+08:00", "--end", "2026-10-02T16:00:00+08:00"))
	must("建立接班班次", runCLI(t, dataPath,
		"shift-add", "--position", "调度", "--owner", "李四",
		"--start", "2026-10-02T16:00:00+08:00", "--end", "2026-10-02T23:00:00+08:00"))
	must("新增事项", runCLI(t, dataPath,
		"item-add", "--shift", "S001", "--content", "原内容：一号泵压力异常",
		"--severity", "normal", "--constraints", "原限制条件：需停电窗口", "--follow", "李四"))
	must("结束交班班次", runCLI(t, dataPath, "shift-close", "--id", "S001"))
	must("发起交接", runCLI(t, dataPath, "handover-create", "--from", "S001", "--to", "S002"))
	must("确认接收 I001", runCLI(t, dataPath,
		"handover-process", "--id", "H001", "--item", "I001",
		"--action", "confirm", "--operator", "李四"))
	return dataPath
}

// breakCLISaving 在数据文件的临时写入路径上放一个目录，使原子保存必然失败；
// 与是否以 root 运行无关，测试可在任意机器上独立重复。
func breakCLISaving(t *testing.T, dataPath string) {
	t.Helper()
	if err := os.Mkdir(dataPath+".tmp", 0o755); err != nil {
		t.Fatalf("制造保存失败：%v", err)
	}
}

// restoreCLISaving 移除故障路径，使保存恢复正常。
func restoreCLISaving(t *testing.T, dataPath string) {
	t.Helper()
	if err := os.RemoveAll(dataPath + ".tmp"); err != nil {
		t.Fatalf("恢复保存：%v", err)
	}
}

// updateArgs 是同时修改四项信息的完整参数。
func updateArgs() []string {
	return []string{
		"item-update", "--id", "I001",
		"--content", "新内容：一号泵压力已复核",
		"--severity", "urgent",
		"--constraints", "新限制条件：夜间禁动",
		"--follow", "王五",
	}
}

// assertCLIUpdateRolledBack 逐项核对：失败的修改没有在任何查询视图中留下痕迹。
func assertCLIUpdateRolledBack(t *testing.T, dataPath string) {
	t.Helper()

	// 凭事项编号查询：仍是失败前的全部信息，没有这次修改的记录。
	show := runCLI(t, dataPath, "item-show", "--id", "I001").ok(t, "失败后查询事项")
	for _, want := range []string{"原内容：一号泵压力异常", "原限制条件：需停电窗口", "李四", "确认接收"} {
		if !strings.Contains(show, want) {
			t.Fatalf("失败后 item-show 应仍显示失败前信息 %q，got:\n%s", want, show)
		}
	}
	for _, unwanted := range []string{"已复核", "夜间禁动", "王五", "修改："} {
		if strings.Contains(show, unwanted) {
			t.Fatalf("失败后 item-show 不应出现未保存的新值或修改记录 %q，got:\n%s", unwanted, show)
		}
	}

	// 当前班次报告与单项查询一致（仍是失败前的值）。
	repB := runCLI(t, dataPath, "shift-show", "--id", "S002").ok(t, "失败后查看当前班次报告")
	if !strings.Contains(repB, "原内容：一号泵压力异常") || strings.Contains(repB, "已复核") {
		t.Fatalf("失败后当前班次报告应仍是失败前信息，got:\n%s", repB)
	}

	// 上一班的结束时记录继续保留当时的内容、限制条件和负责人。
	repA := runCLI(t, dataPath, "shift-show", "--id", "S001").ok(t, "失败后查看上一班结束时记录")
	if !strings.Contains(repA, "原内容：一号泵压力异常") || !strings.Contains(repA, "原限制条件：需停电窗口") ||
		strings.Contains(repA, "已复核") || strings.Contains(repA, "夜间禁动") {
		t.Fatalf("失败后上一班结束时记录应保持当时内容，got:\n%s", repA)
	}

	// 交接清单中的事项原文与确认接收结果不受修改失败影响。
	hShow := runCLI(t, dataPath, "handover-show", "--id", "H001").ok(t, "失败后查看交接")
	if !strings.Contains(hShow, "原内容：一号泵压力异常") || !strings.Contains(hShow, "确认接收") ||
		strings.Contains(hShow, "已复核") {
		t.Fatalf("失败后交接记录应保持接收时原文与结果，got:\n%s", hShow)
	}
}

// TestCLIItemUpdateSaveFailureAtomicRollback 是核心保障：保存失败时命令明确
// 报错、不宣称成功、不把未保存的新值当作修改结果，系统里不留下修改的任何
// 一部分；恢复保存后同样的修改成功，历史记录各自保留原含义。
func TestCLIItemUpdateSaveFailureAtomicRollback(t *testing.T) {
	dataPath := setupReceivedItemForUpdate(t)

	before := hashFile(t, dataPath)
	breakCLISaving(t, dataPath)

	// 同时修改四项信息，本地数据保存失败。
	r := runCLI(t, dataPath, updateArgs()...)
	r.failed(t, "保存失败时修改事项", "写入数据文件失败")
	// 不显示“已修改事项”的成功提示，也不把尚未保存的新值当作修改结果展示。
	if strings.Contains(r.stdout, "已修改事项") || strings.Contains(r.stderr, "已修改事项") {
		t.Fatalf("保存失败不得显示成功提示：stdout=%q stderr=%q", r.stdout, r.stderr)
	}
	if strings.Contains(r.stdout, "已复核") || strings.Contains(r.stdout, "王五") {
		t.Fatalf("保存失败不得展示尚未保存的新值：stdout=%q", r.stdout)
	}

	// 数据文件一个字节都不应改变（原子改名未发生）。
	if after := hashFile(t, dataPath); after != before {
		t.Fatalf("保存失败不得改动数据文件：before=%s after=%s", before, after)
	}

	// 各查询视图都仍是失败前已保存的信息。
	assertCLIUpdateRolledBack(t, dataPath)

	// 恢复正常保存后，对同一事项再次提交同样的修改应能成功。
	restoreCLISaving(t, dataPath)
	out := runCLI(t, dataPath, updateArgs()...).ok(t, "恢复保存后修改事项")
	if !strings.Contains(out, "已修改事项") || !strings.Contains(out, "新内容：一号泵压力已复核") {
		t.Fatalf("成功修改应显示成功提示与新值，got:\n%s", out)
	}

	// 查询展示四项新信息，并新增一次修改经过。
	show := runCLI(t, dataPath, "item-show", "--id", "I001").ok(t, "成功后查询事项")
	for _, want := range []string{"新内容：一号泵压力已复核", "新限制条件：夜间禁动", "王五", "修改："} {
		if !strings.Contains(show, want) {
			t.Fatalf("成功后 item-show 应展示新信息与修改经过 %q，got:\n%s", want, show)
		}
	}

	// 上一班结束时记录以及交接清单中的事项原文不能被新值替换。
	repA := runCLI(t, dataPath, "shift-show", "--id", "S001").ok(t, "成功后查看上一班结束时记录")
	if !strings.Contains(repA, "原内容：一号泵压力异常") || !strings.Contains(repA, "原限制条件：需停电窗口") {
		t.Fatalf("上一班结束时记录不应被新值替换，got:\n%s", repA)
	}
	hShow := runCLI(t, dataPath, "handover-show", "--id", "H001").ok(t, "成功后查看交接")
	if !strings.Contains(hShow, "原内容：一号泵压力异常") || strings.Contains(hShow, "已复核") {
		t.Fatalf("交接清单中的事项原文不应被新值替换，got:\n%s", hShow)
	}
}

// Command handover 是本地班次交接与未关闭事项的命令行入口。
//
// 数据默认保存在当前目录 handover-data.json，可用全局参数 --data 或环境变量
// HANDOVER_DATA 指定。时间统一使用带时区偏移的 RFC3339，如
// 2026-10-02T08:00:00+08:00。
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/bengzyyys/shift-handover/handover"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

const usageText = `用法：handover [--data 文件] <命令> [参数]

数据持久化在本地 JSON 文件中，退出后重新打开数据仍在。
时间使用带时区的 RFC3339，例如 2026-10-02T08:00:00+08:00。

班次：
  shift-add      建立班次        --position 岗位 --owner 负责人 --start 开始 --end 结束
                                 [--note 重叠说明（与同岗位已存班次区间重叠时必填）]
  shift-list     列出全部班次
  shift-close    结束班次        --id 班次编号
  shift-show     按班次查询      --id 班次编号（完整事项/交接/结果）

重叠说明：
  note-add       为重叠班次填说明 --a 班次 --b 班次 --note 说明
  note-list      查看班次涉及的重叠说明 --id 班次

事项：
  item-add       新增事项        --shift 班次 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-update    修改事项        --id 事项编号 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-close     关闭事项        --id 事项编号 --operator 操作人
  item-show      查询事项        --id 事项编号（最新状态、完整处理经过与各次交接当前结果）

交接：
  handover-create   发起交接      --from 交班班次 --to 接班班次
  handover-list     列出全部交接
  handover-show     查看交接      --id 交接编号
  handover-process  接班人处理单项 --id 交接编号 --item 事项编号 \
                                 --action confirm|return|track --operator 操作人 \
                                 [--reason 退回原因] [--note 跟踪说明] [--follow 后续负责人]
  handover-resubmit 交班人补充并重新提交退回项 \
                                 --id 交接编号 --item 事项编号 \
                                 --operator 操作人 --supplement 补充说明
`

func run(argv []string, stdout, stderr io.Writer) int {
	args := append([]string(nil), argv...)
	dataPath, rest, err := splitDataFlag(args, os.Getenv("HANDOVER_DATA"))
	if err != nil {
		// 显式指定了数据文件却没给出有效路径：明确失败，不回落到
		// 环境变量或默认文件，也不展示帮助或任何业务数据。
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if dataPath == "" {
		dataPath = "handover-data.json"
	}

	if len(rest) == 0 || rest[0] == "-h" || rest[0] == "--help" || rest[0] == "help" {
		fmt.Fprint(stdout, usageText)
		return 0
	}

	cmd, cmdArgs := rest[0], rest[1:]
	store, err := handover.Open(dataPath)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	svc := handover.NewService(store)

	out, err := dispatch(svc, cmd, cmdArgs)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if out != "" {
		fmt.Fprint(stdout, out)
		if len(out) > 0 && out[len(out)-1] != '\n' {
			fmt.Fprintln(stdout)
		}
	}
	return 0
}

// valueFlags 是各子命令会带一个值的字符串参数。提取全局 --data 时，
// 这些参数后面的一个 token 是它的值：即使恰好写成 --data 或 --data=...，
// 也只是参数值（如事项内容、限制条件），不能当作数据文件参数取走。
var valueFlags = map[string]bool{
	"id": true, "position": true, "owner": true, "start": true, "end": true,
	"a": true, "b": true, "note": true, "shift": true, "content": true,
	"severity": true, "constraints": true, "follow": true, "operator": true,
	"from": true, "to": true, "item": true, "action": true, "reason": true,
	"supplement": true,
}

// splitDataFlag 从全部输入中抽出全局 --data（--data 路径 与 --data=路径 两种
// 形式，命令前后均可），返回数据文件路径与其余参数。已知参数的 --name value
// 形式中，value 原样保留，不参与 --data 判定；env 为未显式指定时的回退值。
// 显式给出 --data 却没有有效路径（--data 后为空字符串、--data= 后没有内容、
// 或命令末尾只有独立的 --data）时返回错误：这是输入错误，不能按未指定参数
// 回落到 env 或默认文件。
func splitDataFlag(args []string, env string) (dataPath string, rest []string, err error) {
	dataPath = env
	rest = make([]string, 0, len(args))
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if name, ok := flagName(arg); ok && name != "data" && valueFlags[name] {
			// 其他参数的 --name value 形式：下一个 token 是它的值，原样保留。
			rest = append(rest, arg)
			if i+1 < len(args) {
				rest = append(rest, args[i+1])
				i++
			}
			continue
		}
		switch {
		case arg == "--data":
			if i+1 >= len(args) {
				return "", nil, errors.New("--data 后缺少数据文件路径")
			}
			dataPath = args[i+1]
			i++
			if dataPath == "" {
				return "", nil, errors.New("--data 的数据文件路径不能为空")
			}
		case strings.HasPrefix(arg, "--data="):
			dataPath = arg[len("--data="):]
			if dataPath == "" {
				return "", nil, errors.New("--data 的数据文件路径不能为空")
			}
		default:
			rest = append(rest, arg)
		}
	}
	return dataPath, rest, nil
}

// flagName 解析 -name / --name 形式的参数名；带 = 的形式值已内联，返回 false。
func flagName(arg string) (string, bool) {
	if !strings.HasPrefix(arg, "-") || strings.Contains(arg, "=") {
		return "", false
	}
	name := strings.TrimLeft(arg, "-")
	return name, name != ""
}

func dispatch(svc *handover.Service, cmd string, args []string) (string, error) {
	fs := flag.NewFlagSet(cmd, flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	var (
		id, position, owner, startS, endS              string
		a, b                                           string
		shift, content, severityS, constraints, follow string
		operator, from, to                             string
		item, actionS, reason, note, supplement        string
	)
	fs.StringVar(&id, "id", "", "记录编号")
	fs.StringVar(&position, "position", "", "岗位")
	fs.StringVar(&owner, "owner", "", "负责人")
	fs.StringVar(&startS, "start", "", "开始时间 RFC3339")
	fs.StringVar(&endS, "end", "", "结束时间 RFC3339")
	fs.StringVar(&a, "a", "", "班次编号 A")
	fs.StringVar(&b, "b", "", "班次编号 B")
	// note-add 时为重叠说明；handover-process --action track 时为跟踪说明。
	fs.StringVar(&note, "note", "", "重叠说明 / 跟踪说明")
	fs.StringVar(&shift, "shift", "", "班次编号")
	fs.StringVar(&content, "content", "", "事项内容")
	fs.StringVar(&severityS, "severity", "", "严重程度 normal|important|urgent")
	fs.StringVar(&constraints, "constraints", "", "限制条件（可空）")
	// follow 同时用于后续负责人（新增/修改事项）与跟踪后续负责人（track）。
	fs.StringVar(&follow, "follow", "", "后续负责人")
	fs.StringVar(&operator, "operator", "", "操作人")
	fs.StringVar(&from, "from", "", "交班班次编号")
	fs.StringVar(&to, "to", "", "接班班次编号")
	fs.StringVar(&item, "item", "", "事项编号")
	fs.StringVar(&actionS, "action", "", "confirm|return|track")
	fs.StringVar(&reason, "reason", "", "退回原因")
	fs.StringVar(&supplement, "supplement", "", "补充说明")
	if err := fs.Parse(args); err != nil {
		return "", err
	}

	switch cmd {
	case "shift-add":
		start, err := parseTime("--start", startS)
		if err != nil {
			return "", err
		}
		end, err := parseTime("--end", endS)
		if err != nil {
			return "", err
		}
		sh, err := svc.CreateShift(position, owner, start, end, note)
		if err != nil {
			return "", err
		}
		return "已建立班次 " + handover.FormatShift(sh), nil

	case "shift-list":
		shifts := svc.ListShifts()
		if len(shifts) == 0 {
			return "（暂无班次）", nil
		}
		out := ""
		for _, sh := range shifts {
			out += handover.FormatShift(sh) + "\n"
		}
		return out, nil

	case "shift-close":
		sh, err := svc.CloseShift(id)
		if err != nil {
			return "", err
		}
		return "已结束班次 " + handover.FormatShift(sh), nil

	case "shift-show":
		rep, err := svc.ShiftReport(id)
		if err != nil {
			return "", err
		}
		return handover.FormatReport(rep), nil

	case "note-add":
		n, err := svc.AddOverlapNote(a, b, note)
		if err != nil {
			return "", err
		}
		return "已保存重叠说明 " + handover.FormatOverlapNote(n), nil

	case "note-list":
		notes := svc.OverlapNotes(id)
		if len(notes) == 0 {
			return "（无重叠说明）", nil
		}
		out := ""
		for _, n := range notes {
			out += handover.FormatOverlapNote(n) + "\n\n"
		}
		return out, nil

	case "item-add":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.AddItem(shift, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已新增事项\n" + handover.FormatItem(it), nil

	case "item-update":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.UpdateItem(id, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已修改事项\n" + handover.FormatItem(it), nil

	case "item-close":
		it, err := svc.CloseItem(id, operator)
		if err != nil {
			return "", err
		}
		return "已关闭事项\n" + handover.FormatItem(it), nil

	case "item-show":
		j, err := svc.ItemJourney(id)
		if err != nil {
			return "", err
		}
		return handover.FormatItemJourney(j), nil

	case "handover-create":
		h, err := svc.CreateHandover(from, to)
		if err != nil {
			if errors.Is(err, handover.ErrHandoverExists) {
				// 重复发起返回已有记录，不视为失败。
				return "已存在交接记录（重复发起，返回已有记录）\n" + handover.FormatHandover(h), nil
			}
			return "", err
		}
		return "已发起交接\n" + handover.FormatHandover(h), nil

	case "handover-list":
		hs := svc.ListHandovers()
		if len(hs) == 0 {
			return "（暂无交接记录）", nil
		}
		out := ""
		for _, h := range hs {
			out += handover.FormatHandover(h) + "\n"
		}
		return out, nil

	case "handover-show":
		h, err := svc.GetHandover(id)
		if err != nil {
			return "", err
		}
		return handover.FormatHandover(h), nil

	case "handover-process":
		action, err := handover.ParseAction(actionS)
		if err != nil {
			return "", err
		}
		h, err := svc.ProcessEntry(id, item, action, operator, reason, note, follow)
		if err != nil {
			return "", err
		}
		return "已处理\n" + handover.FormatHandover(h), nil

	case "handover-resubmit":
		h, err := svc.ResubmitReturned(id, item, operator, supplement)
		if err != nil {
			return "", err
		}
		return "已补充说明并重新提交\n" + handover.FormatHandover(h), nil

	default:
		return "", fmt.Errorf("未知命令 %q，运行 handover help 查看用法", cmd)
	}
}

func parseTime(name, s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, fmt.Errorf("%s 不能为空，格式为带时区的 RFC3339（如 2026-10-02T08:00:00+08:00）", name)
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, fmt.Errorf("%s 时间格式无效：%w（应为 RFC3339，如 2026-10-02T08:00:00+08:00）", name, err)
	}
	return t, nil
}

package main

import (
	"reflect"
	"strings"
	"testing"
)

func TestSplitDataFlag(t *testing.T) {
	cases := []struct {
		name     string
		args     []string
		env      string
		wantPath string
		wantRest []string
	}{
		{
			name:     "内容恰为 --data=文件 时仍写入显式指定的数据文件",
			args:     []string{"--data", "甲.json", "item-add", "--shift", "S001", "--content", "--data=乙.json", "--severity", "normal", "--follow", "李四"},
			wantPath: "甲.json",
			wantRest: []string{"item-add", "--shift", "S001", "--content", "--data=乙.json", "--severity", "normal", "--follow", "李四"},
		},
		{
			name:     "内容恰为 --data 时后续独立参数仍生效",
			args:     []string{"item-add", "--shift", "S001", "--content", "--data", "--severity", "urgent", "--follow", "王五"},
			wantPath: "",
			wantRest: []string{"item-add", "--shift", "S001", "--content", "--data", "--severity", "urgent", "--follow", "王五"},
		},
		{
			name:     "限制条件恰为 --data= 开头的说明",
			args:     []string{"item-update", "--id", "I001", "--content", "正文", "--constraints", "--data=丙.json 只是说明", "--severity", "normal", "--follow", "赵六"},
			wantPath: "",
			wantRest: []string{"item-update", "--id", "I001", "--content", "正文", "--constraints", "--data=丙.json 只是说明", "--severity", "normal", "--follow", "赵六"},
		},
		{
			name:     "命令前的 --data 路径",
			args:     []string{"--data", "a.json", "shift-list"},
			wantPath: "a.json",
			wantRest: []string{"shift-list"},
		},
		{
			name:     "命令后的 --data 路径",
			args:     []string{"shift-list", "--data", "a.json"},
			wantPath: "a.json",
			wantRest: []string{"shift-list"},
		},
		{
			name:     "--data=路径 形式",
			args:     []string{"item-show", "--id", "I001", "--data=a.json"},
			wantPath: "a.json",
			wantRest: []string{"item-show", "--id", "I001"},
		},
		{
			name:     "未指定时沿用环境变量",
			args:     []string{"shift-list"},
			env:      "env.json",
			wantPath: "env.json",
			wantRest: []string{"shift-list"},
		},
		{
			name:     "显式 --data 优先于环境变量",
			args:     []string{"--data", "explicit.json", "shift-list"},
			env:      "env.json",
			wantPath: "explicit.json",
			wantRest: []string{"shift-list"},
		},
		{
			name:     "--name=value 形式的参数值不受影响",
			args:     []string{"item-add", "--shift=S001", "--content=--data=乙.json", "--severity=normal", "--follow=李四"},
			wantPath: "",
			wantRest: []string{"item-add", "--shift=S001", "--content=--data=乙.json", "--severity=normal", "--follow=李四"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			path, rest, err := splitDataFlag(tc.args, tc.env)
			if err != nil {
				t.Fatalf("splitDataFlag 返回意外错误：%v", err)
			}
			if path != tc.wantPath {
				t.Errorf("dataPath = %q，期望 %q", path, tc.wantPath)
			}
			if !reflect.DeepEqual(rest, tc.wantRest) {
				t.Errorf("rest = %q，期望 %q", rest, tc.wantRest)
			}
		})
	}
}

func TestSplitDataFlagRejectsEmptyOrMissingPath(t *testing.T) {
	cases := []struct {
		name string
		args []string
		env  string
		want string
	}{
		{
			name: "命令前 --data 后为空字符串",
			args: []string{"--data", "", "shift-list"},
			want: "不能为空",
		},
		{
			name: "命令后 --data 后为空字符串",
			args: []string{"shift-list", "--data", ""},
			want: "不能为空",
		},
		{
			name: "--data= 后没有内容",
			args: []string{"shift-list", "--data="},
			want: "不能为空",
		},
		{
			name: "命令末尾只有独立 --data",
			args: []string{"shift-list", "--data"},
			want: "缺少数据文件路径",
		},
		{
			name: "空路径不能回落到环境变量",
			args: []string{"--data", "", "shift-list"},
			env:  "env.json",
			want: "不能为空",
		},
		{
			name: "空路径不能回落到环境变量（--data= 形式）",
			args: []string{"--data=", "shift-list"},
			env:  "env.json",
			want: "不能为空",
		},
		{
			name: "缺少路径不能回落到环境变量",
			args: []string{"shift-list", "--data"},
			env:  "env.json",
			want: "缺少数据文件路径",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			path, rest, err := splitDataFlag(tc.args, tc.env)
			if err == nil {
				t.Fatalf("期望报错，实际成功：path=%q rest=%q", path, rest)
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("错误信息应包含 %q，got %q", tc.want, err.Error())
			}
		})
	}
}

