		hID: h.ID, fromShift: a.ID, toShift: b.ID, idA: idA, idB: idB,
		otherConfirmedAt: otherConfirmedAt,
		preRounds:        0,
		failAt:           tsDay(2, 17, 0),
		failedReason:     "第一次退回原因-失败尝试",
		failedOperator:   "接班人王五",
	}

